def set_cyr_font(run, name="Times New Roman"):
    run.font.name = name
    rPr = run._element.get_or_add_rPr()
    rFonts = rPr.find(qn('w:rFonts'))
    if rFonts is None:
        rFonts = rPr.makeelement(qn('w:rFonts'), {}); rPr.append(rFonts)
    for a in ('w:ascii', 'w:hAnsi', 'w:cs'):
        rFonts.set(qn(a), name)


doc = Document()
# page setup: official Russian convention
sec = doc.sections[0]
sec.page_width = Cm(21); sec.page_height = Cm(29.7)  # A4
sec.top_margin = Cm(2); sec.bottom_margin = Cm(2); sec.left_margin = Cm(3); sec.right_margin = Cm(1.5)
st = doc.styles['Normal']
st.font.name = 'Times New Roman'; st.font.size = Pt(12)
st.element.rPr.rFonts.set(qn('w:cs'), 'Times New Roman')
pf = st.paragraph_format; pf.line_spacing = 1.4; pf.space_after = Pt(8); pf.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY

def para(text, size=12, bold=False, align=WD_ALIGN_PARAGRAPH.JUSTIFY, before=0, after=8, italic=False, color=None):
    p = doc.add_paragraph()
    p.paragraph_format.alignment = align
    p.paragraph_format.space_before = Pt(before); p.paragraph_format.space_after = Pt(after)
    r = p.add_run(text); r.bold = bold; r.italic = italic; r.font.size = Pt(size)
    set_cyr_font(r)
    if color: r.font.color.rgb = color
    return p

# --- header ---
para(TITLE, size=16, bold=True, align=WD_ALIGN_PARAGRAPH.CENTER, after=4)
para(SUB, size=12.5, bold=True, align=WD_ALIGN_PARAGRAPH.CENTER, after=10)
para(INTRO, size=11, italic=True, color=RGBColor(0x44, 0x44, 0x44), after=6)
para("Общий хронометраж: ориентировочно 17–18 минут.", size=11, italic=True, color=RGBColor(0x44, 0x44, 0x44), after=14)

# --- slides ---
for num, title, timing, paras in SLIDES:
    h = doc.add_paragraph(); h.paragraph_format.space_before = Pt(10); h.paragraph_format.space_after = Pt(3)
    r = h.add_run(f"Слайд {num}. {title}"); r.bold = True; r.font.size = Pt(12.5); set_cyr_font(r)
    rt = h.add_run(f"   ({timing})"); rt.italic = True; rt.font.size = Pt(10.5); rt.font.color.rgb = RGBColor(0x88, 0x88, 0x88); set_cyr_font(rt)
    for pt in paras:
        para(pt)

doc.save("Пояснительный_текст_к_презентации.docx")
print("saved docx")
